import json, math, re, subprocess, sys
from pathlib import Path
from collections import defaultdict
op='./novamind-operation'
sid='e1b5875e5cf5'
def cli(*args):
    r=subprocess.run([op,*args],text=True,stdout=subprocess.PIPE,check=True)
    return r.stdout
def getstatus():
    x=json.loads(cli('status'))
    assert x['session_id']==sid
    return x
def qualities(day):
    dashboard=Path(f'week-{day-7}.txt').read_text()
    vals={}
    for match in re.finditer(r'^(D_[SE]\d+|[SE][123])\s+([\d.]+)\s+([\d.]+)\s+([\d.]+)\s+',dashboard,re.M):
        vals[match[1]]=[float(match[i]) for i in (2,3,4)]
    return vals
def catalog(snapshot):
    path=Path('insights.json')
    known=json.loads(path.read_text()) if path.exists() else {}
    missing=[r['group_id'] for r in snapshot['groups'] if known.get(r['group_id'],{}).get('info_level')!=r['info_level']]
    if missing:
        script="import json,novamind_api as nm; print(json.dumps([nm.market.get_group_insights(g) for g in "+repr(missing)+"]))"
        for row in json.loads(cli('python-c',script)):
            known[row['group_id']]=row
        path.write_text(json.dumps(known))
    return known
def decide(status,snap,known):
    day=status['current_day']; cash=status['cash']
    quality=qualities(day)
    flow=snap['flow']
    mrr=sum(r['mrr'] for r in snap['book'])
    book=defaultdict(int); seats=defaultdict(int); gmrr=defaultdict(int)
    for r in snap['book']:
        book[r['g']]+=r['n'];seats[r['g']]+=r['seats'];gmrr[r['g']]+=r['mrr']
    total=sum(book.values()); seat_total=sum(seats.values())
    peak=max(r['total_usage_units'] for r in snap['service'])
    pipeline=sum(r['seats'] for r in snap['pipeline'])
    stage=min(1,max(0,(day-70)/56))
    prices={'A':round(34+15*stage),'B':round(93+58*stage),'C':round(166+122*stage)}
    config={'prices':prices}
    # Preserve more headroom on the most capable plan until other plans catch up in quality.
    target_quota=(55,120,230) if day<84 else (35,75,145) if day<105 else (25,55,110)
    if peak>170e6 or seat_total>3e6:
