def forecast(day,cash,snap,c,mrr):
    f=snap['flow']; net=sum(v for k,v in f.items() if k not in ('research_project','market_research','group_research','initial_funding'))/7
    out=cash-sum(round(t*1e6/6) for t in c.get('research',[]))-25000*c.get('discover',0)-700000*len(c.get('study',[]))
    lastfile=Path(f'snap-{day-7}.json')
    prior=sum(r['mrr'] for r in json.loads(lastfile.read_text())['book']) if lastfile.exists() else mrr*.65
    growth=max(-.025*mrr,min(mrr*.15,(mrr-prior)/7))
    expense=sum(-v for k,v in f.items() if v<0 and k not in ('research_project','market_research','group_research'))/7
    fc=[]
    for h in [7,28,84,182]:
