        settings['ads']['targeted_spend']={ch:{g:round(v*mult) for g,v in vals.items()} for ch,vals in settings['ads']['targeted_spend'].items()}
    if day<112 or stress:
        expected_weekly=(week_income*.82-flow.get('ad_revenue',0)*.8+flow.get('compute',0)*1.1-7*(settings['spend']['operations']+settings['spend']['development']+sum(settings['dev']['targeted_spend'].values())+sum(sum(v.values()) for v in settings['ads']['targeted_spend'].values())+75000))
        point=max(0,cash+expected_weekly)
        forecasts[:3]=[round(point),round(max(0,point-max(1500000,week_income*.8))),round(point+max(2200000,week_income*1.1))]
    return why,forecasts
